        return "Error: Enter a valid phone number, e.g. +1 555 000 1234.";
      return null;
    },
  },
};

/* ── DOM helpers ──────────────────────────────────────────── */
function getField(name) {
  return document.getElementById(name);
}
function getError(name) {
  return document.getElementById(`${name}-error`);
}

function showError(name, message) {
  const input = getField(name);
  const errorEl = getError(name);
  if (!input || !errorEl) return;
  input.setAttribute("aria-invalid", "true");
  errorEl.textContent = message;
  errorEl.classList.add("visible");
}

function clearError(name) {
  const input = getField(name);
  const errorEl = getError(name);
  if (!input || !errorEl) return;
  input.removeAttribute("aria-invalid");
  errorEl.textContent = "";
  errorEl.classList.remove("visible");
}

function validateField(name) {
  const input = getField(name);
  if (!input) return true;
  const error = RULES[name]?.validate(input.value);
  if (error) { showError(name, error); return false; }
  clearError(name);
  return true;
}

/* ── Blur-time validation ─────────────────────────────────── */
["fullName", "email", "phone"].forEach((name) => {
  const input = getField(name);
  if (!input) return;
  input.addEventListener("blur", () => validateField(name));
