    /* Focus first invalid field */
    getField(invalid[0].name)?.focus();

    /* Announce error count via alert region */
    statusEl.className = "form-status error";
    statusEl.textContent =
      `${invalid.length} field${invalid.length > 1 ? "s need" : " needs"} your attention. Review the errors below.`;
    return;
  }

  /* Simulate successful submission */
  form.reset();
  fields.forEach((name) => clearError(name));
  statusEl.className = "form-status success";
  statusEl.textContent = "Your message has been sent. We'll get back to you shortly.";
  document.getElementById("fullName").focus();
});
