  --color-primary:       #4361ee;
  --color-primary-dark:  #3451d1;
  --color-error:         #c0392b;
  --color-error-bg:      #fef2f2;
  --color-error-border:  #fca5a5;
  --color-success:       #15803d;
  --color-success-bg:    #f0fdf4;
  --color-success-border:#86efac;
  --color-helper:        #4b5563;
  --radius:              10px;
  --shadow:              0 4px 24px rgba(0,0,0,.08);
  --transition:          .18s ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem 4rem;
  line-height: 1.5;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page header ──────────────────────────────────────────── */
.page-header {
  width: 100%;
  max-width: 560px;
  margin-bottom: 2rem;
  text-align: center;
}
.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}
.page-header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .975rem;
}

/* ── Card ─────────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2.25rem 2rem;
  width: 100%;
  max-width: 560px;
}

/* ── Required legend ──────────────────────────────────────── */
.required-note {
  font-size: .85rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-note abbr {
  color: var(--color-error);
  text-decoration: none;
  font-weight: 700;
}

/* ── Form fields ──────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: .375rem;
  margin-bottom: 1.25rem;
}

.form-field label {
  font-size: .9rem;
  font-weight: 600;
  color: var(--color-label);
  display: flex;
  align-items: center;
  gap: .25rem;
}
.required-star {
  color: var(--color-error);
  font-size: 1rem;
  line-height: 1;
}

.form-field input {
  width: 100%;
  padding: .625rem .875rem;
  border: 1.5px solid var(--color-border);
  border-radius: 8px;
  font-size: 1rem;
  color: var(--color-text);
  background: var(--color-surface);
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}
.form-field input::placeholder { color: #9ca3af; }

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(67,97,238,.2);
}

/* Invalid state */
.form-field input[aria-invalid="true"] {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
}
.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(192,57,43,.2);
}

/* ── Helper & error text ──────────────────────────────────── */
.helper-text {
  font-size: .82rem;
  color: var(--color-helper);
}

.error-text {
  font-size: .82rem;
  color: var(--color-error);
  font-weight: 500;
  display: none;
  align-items: flex-start;
  gap: .3rem;
}
.error-text.visible { display: flex; }
.error-text::before {
  content: "⚠";
  flex-shrink: 0;
  margin-top: .05em;
}

/* ── Submit button ────────────────────────────────────────── */
.btn-submit {
  margin-top: .75rem;
  width: 100%;
  padding: .75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  letter-spacing: .01em;
}
.btn-submit:hover { background: var(--color-primary-dark); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}
.btn-submit:active { transform: translateY(1px); }

/* ── Status banner ────────────────────────────────────────── */
.form-status {
  padding: .875rem 1rem;
  border-radius: 8px;
  font-size: .9rem;
  font-weight: 500;
  margin-bottom: 1.25rem;
  display: none;
}
.form-status.success {
  display: block;
  color: var(--color-success);
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
}
.form-status.error {
  display: block;
  color: var(--color-error);
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
}

/* ── Forced colors / high-contrast ───────────────────────── */
@media (forced-colors: active) {
  .form-field input:focus,
  .btn-submit:focus-visible { outline: 3px solid ButtonText; }
  .form-field input[aria-invalid="true"] { border-color: Mark; }
}

/* ── Reduced motion ───────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow / narrow viewport ─────────────────────────────── */
@media (max-width: 400px) {
  .card { padding: 1.5rem 1rem; }
  .page-header h1 { font-size: 1.4rem; }
}
